mapper.select:
SELECT c.contract_id, c.contract_no, c.contract_name, c.amount, c.dept_id, c.create_by, c.create_time, d.dept_name, u.nick_name AS create_by_name FROM sys_contract c LEFT JOIN sys_dept d ON d.dept_id = c.dept_id LEFT JOIN sys_user u ON u.user_id = c.create_by WHERE c.del_flag = '0'
AND c.contract_name LIKE CONCAT('%', #{contractName}, '%')
AND c.dept_id = #{deptId}
AND ${params.dataScope}
ORDER BY c.contract_id
